package com.lianxibu.site.service.jobs;

import com.lianxibu.site.repository.jobs.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Every requested native count event and its original registered P1 source share the final RR snapshot. */
public final class EntityHeatSourceOriginService {
    public record Missing(String eventId,String reason){@Override public String toString(){return "EntityHeatSourceOriginGap[redacted]";}}
    private record Resolved(Map<String,EntityHeatDedupOrigin.Origin> origins,List<Missing> missing,long bytes){ }
    public static final class Captured {
        private final Object issuer;private final Instant cutoff;private final Set<String> requested;private final Map<String,EntityHeatEventProofService.Proven> events;private final Map<String,JdbcEntityHeatOriginHeaders.Header> headers;private final Map<LocalDate,NewsDayReportComponentService.Captured> days;private final Resolved resolved;
        private Captured(Object issuer,Instant cutoff,Set<String> requested,Map<String,EntityHeatEventProofService.Proven> events,Map<String,JdbcEntityHeatOriginHeaders.Header> headers,Map<LocalDate,NewsDayReportComponentService.Captured> days,Resolved resolved){this.issuer=issuer;this.cutoff=cutoff;this.requested=Set.copyOf(requested);this.events=immutable(events);this.headers=immutable(headers);this.days=immutable(days);this.resolved=resolved;}
        public Instant cutoff(){return cutoff;}public Set<String> requested(){return requested;}public Map<String,EntityHeatDedupOrigin.Origin> origins(){return resolved.origins();}public List<Missing> missing(){return resolved.missing();}public Map<String,JdbcEntityHeatOriginHeaders.Header> headers(){return headers;}public Collection<NewsDayReportComponentService.Captured> days(){return days.values().stream().filter(Objects::nonNull).toList();}public long originalByteSize(){return resolved.bytes();}
        @Override public String toString(){return "ActualOriginalEntityHeatSources[redacted]";}
    }
    private final Object issuer=new Object();private final JdbcEntityHeatOriginHeaders headers;private final EntityHeatEventProofService events;private final NewsDayReportComponentService days;private final SourceDayCohortSealService cohorts;private final FrozenSourceStagePlanService plans;private final SourceDedupResultProofService fragments;private final TransactionTemplate reads;private final int budget;
    public EntityHeatSourceOriginService(JdbcEntityHeatOriginHeaders headers,EntityHeatEventProofService events,NewsDayReportComponentService days,SourceDayCohortSealService cohorts,FrozenSourceStagePlanService plans,SourceDedupResultProofService fragments,PlatformTransactionManager tx){this(headers,events,days,cohorts,plans,fragments,tx,EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES);}
    public EntityHeatSourceOriginService(JdbcEntityHeatOriginHeaders headers,EntityHeatEventProofService events,NewsDayReportComponentService days,SourceDayCohortSealService cohorts,FrozenSourceStagePlanService plans,SourceDedupResultProofService fragments,PlatformTransactionManager tx,int budget){this.headers=Objects.requireNonNull(headers);this.events=Objects.requireNonNull(events);this.days=Objects.requireNonNull(days);this.cohorts=Objects.requireNonNull(cohorts);this.plans=Objects.requireNonNull(plans);this.fragments=Objects.requireNonNull(fragments);if(budget<1024||budget>EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES)throw invalid();this.budget=budget;reads=new TransactionTemplate(Objects.requireNonNull(tx));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);}
    public Captured capture(Collection<String> requested,Instant cutoff){outside();Objects.requireNonNull(requested);if(cutoff==null||cutoff.getNano()%1000!=0)throw invalid();var ids=new TreeSet<String>();for(String id:requested){if(id==null||!id.matches("[0-9a-f]{64}")||!ids.add(id))throw invalid();if((long)ids.size()*256>budget)throw new GenerationFlowService.CapacityGuarded();}
        var nativeEvents=new TreeMap<String,EntityHeatEventProofService.Proven>();for(String id:ids)nativeEvents.put(id,events.find(id));var nativeHeaders=Objects.requireNonNull(reads.execute(s->{var found=new TreeMap<String,JdbcEntityHeatOriginHeaders.Header>();for(var entry:nativeEvents.entrySet())if(entry.getValue()!=null)found.put(entry.getKey(),headers.read(entry.getValue().itemId()));return found;}));
        var originals=new TreeMap<LocalDate,NewsDayReportComponentService.Captured>();for(var header:nativeHeaders.values())if(header!=null&&!header.createdAt().isAfter(cutoff)&&!header.day().isAfter(cutoff.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().minusDays(1)))originals.putIfAbsent(header.day(),null);for(var day:new ArrayList<>(originals.keySet()))originals.put(day,days.capture(day,cutoff));
        return reads.execute(s->new Captured(issuer,cutoff,ids,nativeEvents,nativeHeaders,originals,resolve(cutoff,ids,nativeEvents,nativeHeaders,originals)));
    }
    public Captured verifyObserved(Captured captured){readonly();if(captured==null||captured.issuer!=issuer)throw invalid();var fresh=resolve(captured.cutoff,captured.requested,captured.events,captured.headers,captured.days);if(!captured.resolved.equals(fresh))throw invalid();return captured;}
    private Resolved resolve(Instant cutoff,Set<String> requested,Map<String,EntityHeatEventProofService.Proven> nativeEvents,Map<String,JdbcEntityHeatOriginHeaders.Header> nativeHeaders,Map<LocalDate,NewsDayReportComponentService.Captured> originals){readonly();long bytes=0;
        for(var entry:originals.entrySet()){var original=entry.getValue();if(original==null){if(cohorts.readObserved(entry.getKey())!=null)throw invalid();}else{days.verifyObserved(original);bytes=add(bytes,original.originalByteSize());}}
        var values=new TreeMap<String,EntityHeatDedupOrigin.Origin>();var gaps=new ArrayList<Missing>();var planCache=new HashMap<FrozenSourceStagePlan.Reference,SourcePartitionPlanner.Plan>();var fragmentCache=new HashMap<String,SourceDedupResultProofService.Applied>();
        for(String id:new TreeSet<>(requested)){var event=nativeEvents.get(id);if(event==null){if(events.readObserved(id)!=null)throw invalid();gaps.add(new Missing(id,"count_event_unknown"));continue;}events.verifyObserved(event);bytes=add(bytes,size(event.event().payloadJson())+size(event.event().targetJson())+512L);var header=nativeHeaders.get(id);if(!Objects.equals(header,headers.read(event.itemId())))throw invalid();if(event.event().actedAt().isAfter(cutoff)){gaps.add(new Missing(id,"event_after_cutoff"));continue;}if(!event.hasCompleteTouchedFormat()){gaps.add(new Missing(id,"count_event_format_unproven"));continue;}if(header==null){gaps.add(new Missing(id,"source_item_missing"));continue;}bytes=add(bytes,size(header.sourceItemId())+512L);if(header.createdAt().isAfter(cutoff)||header.day().isAfter(cutoff.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().minusDays(1))){gaps.add(new Missing(id,"source_item_after_cutoff"));continue;}
            var original=originals.get(header.day());if(original==null){gaps.add(new Missing(id,"source_day_unproven"));continue;}var admitted=original.includedDedupPlans().stream().filter(s->s.sourceId().equals(header.sourceId())&&s.runId().equals(header.runId())&&s.day().equals(header.day())).toList();if(admitted.size()>1)throw invalid();if(admitted.isEmpty()){gaps.add(new Missing(id,"source_not_included"));continue;}var reference=admitted.getFirst().reference();var plan=planCache.get(reference);if(plan==null){plan=plans.readImmutable(reference);if(plan.stage()!=GenerationFlowService.Stage.NEWS_DEDUP||plan.scope()==null||!plan.scope().businessDate().equals(header.day()))throw invalid();planCache.put(reference,plan);}
            var matching=plan.chunks().stream().filter(c->c.itemIds().contains(event.itemId())).toList();if(matching.size()>1)throw invalid();if(matching.isEmpty()){gaps.add(new Missing(id,"item_not_in_original_plan"));continue;}var chunk=matching.getFirst();String key=reference.ownerId()+":"+chunk.rootId();var applied=fragmentCache.get(key);if(!fragmentCache.containsKey(key)){applied=fragments.readAppliedBatch(reference,List.of(chunk.rootId())).get(chunk.rootId());fragmentCache.put(key,applied);bytes=add(bytes,size(chunk.snapshotJson())+size(chunk.requestJson())+256L);if(applied!=null)bytes=add(bytes,size(applied.proof().result().payloadJson()));}
            if(applied==null||applied.appliedAt().isAfter(cutoff)){gaps.add(new Missing(id,"applied_fragment_unproven"));continue;}var origin=EntityHeatDedupOrigin.bind(event.event(),chunk,applied.proof());var fact=applied.proof().members().stream().filter(m->m.itemId().equals(event.itemId())).findFirst().orElseThrow(EntityHeatSourceOriginService::invalid);if(!header.itemId().equals(origin.itemId())||!header.runId().equals(origin.runId())||!header.sourceId().equals(origin.sourceId())||!header.sourceItemId().equals(origin.sourceItemId())||!header.day().equals(origin.day())||header.revision()<fact.revision())throw invalid();bytes=add(bytes,size(origin.originalBodyJson())+256L);values.put(id,origin);
        }
        return new Resolved(Collections.unmodifiableMap(values),List.copyOf(gaps),bytes);
    }
    private long add(long bytes,long next){long result=Math.addExact(bytes,next);if(result>budget)throw new GenerationFlowService.CapacityGuarded();return result;}
    private static long size(String value){return value==null?0:value.getBytes(StandardCharsets.UTF_8).length;}
    private static <K,V> Map<K,V> immutable(Map<K,V> value){return Collections.unmodifiableMap(new LinkedHashMap<>(value));}
    private static void outside(){if(TransactionSynchronizationManager.isActualTransactionActive())throw invalid();}
    private static void readonly(){if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!Integer.valueOf(TransactionDefinition.ISOLATION_REPEATABLE_READ).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel()))throw invalid();}
    private static IllegalStateException invalid(){return new IllegalStateException("actual original entity count sources unavailable");}
}
